"""Pascal VOC annotation handling for HOD26.

Boxes live in cube coordinates (the XML ``size`` is the cube's W/H/16),
so they need no rescaling when the model consumes decoded cubes.
"""


import xml.etree.ElementTree as ET
from dataclasses import dataclass
from pathlib import Path

# Order is authoritative: it is the competition's class.txt, and its index
# is the class_id expected in the submission.
CLASSES = [
    "apple", "apple_plastic", "badminton", "banana", "banana_plastic",
    "car", "car_toy", "charger_head", "e-bike", "egg",
    "egg_plastic", "egg_wood", "orange", "orange_plastic", "people",
    "rubik", "stone_block", "table_tennis",
]
CLASS_TO_ID = {c: i for i, c in enumerate(CLASSES)}

# Classes that a pseudo-RGB composite cannot separate from its partner by
# shape alone — the pairs that make this a *hyperspectral* problem.
MATERIAL_GROUPS = [
    ("apple", "apple_plastic"),
    ("banana", "banana_plastic"),
    ("orange", "orange_plastic"),
    ("egg", "egg_plastic", "egg_wood"),
    ("car", "car_toy"),
]


@dataclass(frozen=True)
class Box:
    cls_id: int
    x1: int
    y1: int
    x2: int
    y2: int
    difficult: bool = False

    @property
    def area(self) -> float:
        return max(0, self.x2 - self.x1) * max(0, self.y2 - self.y1)


@dataclass(frozen=True)
class Annotation:
    image_id: int
    width: int
    height: int
    depth: int
    boxes: tuple[Box, ...]


def parse(path) -> Annotation:
    """Parse one VOC XML. Unknown class names raise rather than silently drop."""
    path = Path(path)
    root = ET.parse(path).getroot()
    size = root.find("size")
    w, h = int(size.findtext("width")), int(size.findtext("height"))
    depth = int(size.findtext("depth") or 16)

    boxes = []
    for obj in root.findall("object"):
        name = (obj.findtext("name") or "").strip()
        if name not in CLASS_TO_ID:
            raise KeyError(f"{path}: unknown class {name!r}")
        bb = obj.find("bndbox")
        # VOC is nominally 1-indexed and inclusive; this dataset is already
        # 0-indexed pixel coordinates, so take them as-is and only clamp.
        x1 = max(0, min(w, int(float(bb.findtext("xmin")))))
        y1 = max(0, min(h, int(float(bb.findtext("ymin")))))
        x2 = max(0, min(w, int(float(bb.findtext("xmax")))))
        y2 = max(0, min(h, int(float(bb.findtext("ymax")))))
        if x2 <= x1 or y2 <= y1:  # zero-area boxes would poison the metric
            continue
        boxes.append(
            Box(CLASS_TO_ID[name], x1, y1, x2, y2,
                bool(int(obj.findtext("difficult") or 0)))
        )
    return Annotation(int(path.stem), w, h, depth, tuple(boxes))

# ---- inlined from src/hod26/coco_eval.py ------------------------------
"""Local scorer mirroring the official HOD26 metric.

Organizers confirmed (forum #729747): pycocotools COCOeval in bbox mode,
IoU 0.50:0.05:0.95, 101-point interpolation, macro-averaged over classes
that have ground truth. mAP@0.5 is the same procedure at IoU 0.50.
"""


import contextlib
import io

import numpy as np
from pycocotools.coco import COCO
from pycocotools.cocoeval import COCOeval



def _gt_dict(anns) -> dict:
    images, annotations = [], []
    for a in anns:
        images.append({"id": a.image_id, "width": a.width, "height": a.height})
        for b in a.boxes:
            annotations.append({
                "id": len(annotations) + 1,
                "image_id": a.image_id,
                "category_id": b.cls_id,
                "bbox": [b.x1, b.y1, b.x2 - b.x1, b.y2 - b.y1],  # COCO xywh
                "area": float(b.area),
                "iscrowd": 0,
            })
    return {
        "images": images,
        "annotations": annotations,
        "categories": [{"id": i, "name": n} for i, n in enumerate(CLASSES)],
    }


def evaluate(anns, preds, per_class: bool = False) -> dict:
    """Score predictions against annotations.

    ``preds`` rows are ``(image_id, class_id, confidence, x1, y1, x2, y2)``.
    Returns mAP@[.5:.95] (primary), mAP@0.5 (secondary), and optionally per-class AP.
    """
    gt = COCO()
    gt.dataset = _gt_dict(anns)
    with contextlib.redirect_stdout(io.StringIO()):
        gt.createIndex()

    if not len(preds):
        return {"mAP": 0.0, "mAP50": 0.0, **({"per_class": {}} if per_class else {})}

    dets = [{
        "image_id": int(r[0]), "category_id": int(r[1]), "score": float(r[2]),
        "bbox": [float(r[3]), float(r[4]), float(r[5]) - float(r[3]), float(r[6]) - float(r[4])],
    } for r in preds]

    with contextlib.redirect_stdout(io.StringIO()):
        dt = gt.loadRes(dets)
        e = COCOeval(gt, dt, "bbox")
        e.evaluate(); e.accumulate(); e.summarize()

    out = {"mAP": float(e.stats[0]), "mAP50": float(e.stats[1])}
    if per_class:
        # precision: [TxRxKxAxM]; take all-area, maxDet=100, average over IoU+recall
        prec = e.eval["precision"][:, :, :, 0, -1]
        gt_classes = {a["category_id"] for a in gt.dataset["annotations"]}
        out["per_class"] = {}
        for k, name in enumerate(CLASSES):
            if k not in gt_classes:
                continue
            p = prec[:, :, k]
            p = p[p > -1]
            out["per_class"][name] = float(np.mean(p)) if p.size else 0.0
    return out

